async function uploadStorageObject(file, path, retried) {
  let authToken = await getStorageAuthToken(),
    res = await fetch(SUPABASE_URL + "/storage/v1/object/" + BUCKET_NAME + "/" + path, {
      method: "POST",
      headers: {
        apikey: SUPABASE_ANON,
        Authorization: "Bearer " + authToken,
        "Content-Type": file.type || "application/octet-stream",
      },
      body: file,
    });
  if (!res.ok) {
    const errText = await res.text();
    if (
      !retried &&
      (400 === res.status || 401 === res.status || 403 === res.status) &&
      hasAdminSession() &&
      /exp|jwt|token|unauthorized|claim/i.test(errText) &&
      "function" == typeof refreshAdminToken
    ) {
      try {
        sessionStorage.removeItem("admin_token");
      } catch (_) {}
      if (await refreshAdminToken()) return uploadStorageObject(file, path, !0);
    }
    throw new Error("File upload failed: " + errText);
  }
  return SUPABASE_URL + "/storage/v1/object/public/" + BUCKET_NAME + "/" + path;
}
