          file.name && file.name.includes(".")
            ? file.name.split(".").pop()
            : file.type.split("/")[1] || "jpg",
        path =
          (folder ? folder + "/" : "") +
          Date.now() +
          "-" +
          Math.random().toString(36).slice(2, 8) +
          "." +
          ext;
